CREATE POLICY finance_files_select ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'finance-documents' AND public.is_webmaster());
CREATE POLICY finance_files_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'finance-documents' AND public.is_webmaster());
CREATE POLICY finance_files_update ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'finance-documents' AND public.is_webmaster()) WITH CHECK (bucket_id = 'finance-documents' AND public.is_webmaster());
CREATE POLICY finance_files_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'finance-documents' AND public.is_webmaster());